<script setup>
import {Head,Link,useForm,usePage} from '@inertiajs/vue3';import {computed,ref} from 'vue';import TurnstileWidget from '../../Components/TurnstileWidget.vue';import CustomerShell from '../../Components/CustomerShell.vue';
const page=usePage(),turnstile=ref(null),security=computed(()=>page.props.security||{}),form=useForm({email:'',turnstile_token:''});const submit=()=>{if(form.processing)return;form.post('/forgot-password',{onFinish:()=>{form.turnstile_token='';turnstile.value?.reset()}})};
</script><template><Head title="Lupa kata sandi"/><CustomerShell compact-footer><main class="lf-auth-wrap"><form class="lf-auth-card" @submit.prevent="submit"><p class="lf-eyebrow">Pemulihan akun</p><h1>Atur ulang kata sandi</h1><p>Masukkan email akun LFAMILIA untuk menerima tautan reset.</p><p v-if="page.props.status" role="status" class="rounded-lg border border-[#b9ff35]/20 bg-[#b9ff35]/10 p-2 text-[10px] text-[#cfff72]">{{page.props.status}}</p><label class="text-[10px] font-semibold text-white/70">Email<input v-model="form.email" type="email" name="email" autocomplete="email" placeholder="Masukkan email akun" :aria-invalid="Boolean(form.errors.email)" required><span v-if="form.errors.email" role="alert" class="mt-1 block text-xs text-red-300">{{form.errors.email}}</span></label><TurnstileWidget v-if="security.turnstile_required" ref="turnstile" :site-key="security.turnstile_site_key" :action="security.turnstile_action" @token="form.turnstile_token=$event"/><p v-if="form.errors.turnstile_token" role="alert" class="mt-2 text-xs text-red-300">{{form.errors.turnstile_token}}</p><button type="submit" class="lf-primary mt-3 w-full" :disabled="form.processing">{{form.processing?'Mengirim…':'Kirim tautan reset'}}</button><div class="lf-auth-links justify-end"><Link href="/login">Kembali ke masuk</Link></div></form></main></CustomerShell></template>